# Not autogenerated.
import json
from pathlib import Path

from check_benchmark_regressions import main


def write_estimate(
    root: Path,
    benchmark: str,
    result_directory: str,
    lower: float = -0.02,
    point: float = 0.0,
    upper: float = 0.02,
) -> Path:
    path = root / benchmark / result_directory / "estimates.json"
    path.parent.mkdir(parents=True)
    estimate = {
        "confidence_interval": {
            "confidence_level": 0.95,
            "lower_bound": lower,
            "upper_bound": upper,
        },
        "point_estimate": point,
        "standard_error": 0.01,
    }
    path.write_text(json.dumps({"mean": estimate, "median": estimate}))
    return path


def test_complete_named_baseline_passes(tmp_path: Path) -> None:
    write_estimate(tmp_path, "group/one/round_1", "lobo-main")
    write_estimate(tmp_path, "group/two/round_1", "lobo-main")

    result = main(
        [
            "verify-baseline",
            "--criterion-dir",
            str(tmp_path),
            "--name",
            "lobo-main",
            "--expected",
            "2",
        ]
    )

    assert result == 0


def test_incomplete_named_baseline_fails(tmp_path: Path) -> None:
    write_estimate(tmp_path, "group/one/round_1", "lobo-main")

    result = main(
        [
            "verify-baseline",
            "--criterion-dir",
            str(tmp_path),
            "--name",
            "lobo-main",
            "--expected",
            "2",
        ]
    )

    assert result == 2


def test_comparison_inside_threshold_passes(tmp_path: Path) -> None:
    estimate = write_estimate(
        tmp_path,
        "group/one/round_1",
        "change",
        lower=0.04,
        point=0.08,
        upper=0.12,
    )

    result = main(
        [
            "check",
            "--criterion-dir",
            str(tmp_path),
            "--since",
            str(estimate.stat().st_mtime - 1),
            "--expected",
            "1",
            "--rounds-per-scenario",
            "1",
            "--max-regression-percent",
            "10",
        ]
    )

    assert result == 0


def test_statistically_supported_majority_regression_fails(tmp_path: Path) -> None:
    estimates = [
        write_estimate(
            tmp_path,
            f"group/one/round_{round_number}",
            "change",
            lower=0.11 if round_number <= 3 else 0.01,
            point=0.14 if round_number <= 3 else 0.02,
            upper=0.17 if round_number <= 3 else 0.03,
        )
        for round_number in range(1, 6)
    ]

    result = main(
        [
            "check",
            "--criterion-dir",
            str(tmp_path),
            "--since",
            str(min(path.stat().st_mtime for path in estimates) - 1),
            "--expected",
            "5",
            "--rounds-per-scenario",
            "5",
            "--max-regression-percent",
            "10",
        ]
    )

    assert result == 1


def test_one_noisy_round_does_not_fail_five_round_scenario(tmp_path: Path) -> None:
    estimates = [
        write_estimate(
            tmp_path,
            f"group/one/round_{round_number}",
            "change",
            lower=0.11 if round_number == 1 else -0.01,
            point=0.14 if round_number == 1 else 0.01,
            upper=0.17 if round_number == 1 else 0.03,
        )
        for round_number in range(1, 6)
    ]

    result = main(
        [
            "check",
            "--criterion-dir",
            str(tmp_path),
            "--since",
            str(min(path.stat().st_mtime for path in estimates) - 1),
            "--expected",
            "5",
            "--rounds-per-scenario",
            "5",
            "--max-regression-percent",
            "10",
        ]
    )

    assert result == 0


def test_stale_or_missing_comparison_results_fail_closed(tmp_path: Path) -> None:
    estimate = write_estimate(tmp_path, "group/one/round_1", "change")

    result = main(
        [
            "check",
            "--criterion-dir",
            str(tmp_path),
            "--since",
            str(estimate.stat().st_mtime + 1),
            "--expected",
            "1",
            "--rounds-per-scenario",
            "1",
            "--max-regression-percent",
            "10",
        ]
    )

    assert result == 2
